using System;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using PeerChatDesktop;
class UnifiedCompletionDiagnosticsTest {
    static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
    static void Check(bool v,string reason){if(!v)throw new Exception("Unified completion: "+reason);}
    static object Get(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,F).Invoke(o,args);}
    static IEnumerable<T> Walk<T>(DependencyObject o)where T:DependencyObject{for(int n=0;n<VisualTreeHelper.GetChildrenCount(o);n++){var c=VisualTreeHelper.GetChild(o,n);if(c is T)yield return (T)c;foreach(var child in Walk<T>(c))yield return child;}}
    static string Flat(DiagnosticUiSnapshot view){return String.Join("\n",view.Pages.SelectMany(p=>p.Panels).SelectMany(p=>p.Metrics).Select(m=>m.Label+": "+m.Value));}
    static void Capture(Window w,string path){w.UpdateLayout();var surface=(FrameworkElement)w.Content;var bmp=new RenderTargetBitmap((int)Math.Ceiling(surface.ActualWidth),(int)Math.Ceiling(surface.ActualHeight),96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen())dc.DrawRectangle(new VisualBrush(surface),null,new Rect(0,0,surface.ActualWidth,surface.ActualHeight));bmp.Render(drawing);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var s=System.IO.File.Create(path))png.Save(s);}
    public static async Task Run(DesktopApplication desktop,string directory){
        var input=new HistoryDiagnosticInput{Scope="fixture-profile/account:4/device:reader/auth-session:1",Device=new string('1',64),Source=new string('2',64),Account=4,Current=true,Activity="Connecting",State="Connecting to archive",Running=true,Enabled=true,Automatic=true,Scan=8,Processed=12,Imported=3,Conversations=1,Unresolved=2,ProvidedQueued=40,Providers=new[]{new string('3',64)},Result=1,ResultAt=1791846000000,ResultImported=22,ResultConversations=2,ResultSource=new string('4',64),LastSuccessful=1791846000000,Native="scope=archive_history account=4 local_device="+new string('1',64)+"\narchive_route connected=1 pending=0 winner=5 last_failure=token=fixture-secret\narchive_transport attempt=4 role=reader stage=archive_control\nmessage_content=PRIVATE MESSAGE FIXTURE\nsource_eligibility="+new string('2',64)+" result=allowed"};
        var history=new HistoryDiagnosticHistory();history.Observe(input,DateTime.UtcNow);var view=HistoryDiagnosticProjection.Read(input,history);string text=Flat(view);Check(text.Contains("Connecting")&&text.Contains("22")&&text.Contains("Full"),"current scan separate from previous success");Check(text.Contains("Verified new durable imports: 3")&&text.Contains("Source records queued including retries: 40"),"source queued not imports");Check(text.Contains("Deduplicated record count: N/A")&&text.Contains("no reliable total"),"no fabricated deductions or progress total");string export=HistoryDiagnosticProjection.Export(view);Check(!export.Contains("fixture-secret")&&!export.Contains("PRIVATE MESSAGE FIXTURE"),"history export redaction and content exclusion");Check(export.Contains("stage=archive_control")&&export.Contains("result=allowed"),"native evidence preserved");
        input.Activity="Failed";input.Result=2;input.Unresolved=5;history.Observe(input,DateTime.UtcNow);Check(Flat(HistoryDiagnosticProjection.Read(input,history)).Contains("Partial"),"partial outcome independent of failure activity");for(int i=0;i<100;i++){input.Imported=i;history.Observe(input,DateTime.UtcNow);}Check(history.Events.Length==64,"bounded observed history");input.Scope="different-account";input.Current=false;history.Observe(input,DateTime.UtcNow);Check(history.Events.Length==0&&!Flat(HistoryDiagnosticProjection.Read(input,history)).Contains("Verified new durable imports: 99"),"account invalidation clears observations and counts");
        input.Scope="fixture-owner";input.Current=true;input.Activity="Importing";input.State="Synchronizing history";input.Result=1;input.Imported=12;input.Unresolved=0;
        Set(desktop,"historyDiagnosticTestInput",new Func<HistoryDiagnosticInput>(()=>input));Call(desktop,"OpenContextDiagnostics",DiagnosticSection.HistorySync,input.Device);var window=(Window)Get(desktop,"groupDiagnosticWindow");window.ShowInTaskbar=false;window.ShowActivated=false;window.Left=-20000;window.Width=1080;window.Height=820;var tabs=(TabControl)Get(desktop,"groupDiagnosticTabs");Check(tabs.Items.Count==4,"history four approved tabs");var snapshot=(DiagnosticUiSnapshot)Get(desktop,"historyDiagnosticView");Check(!snapshot.Sample,"normal provider is real, no sample fallback");var footer=((DockPanel)window.Content).Children.OfType<WrapPanel>().Single();Check(!footer.Children.OfType<Button>().Single(b=>Object.Equals(b.Tag,"Pause graphs")).IsEnabled,"no graph control falsely enabled");
        var page=((TabItem)tabs.Items[0]).Content;input.Imported=13;await Task.Delay(1400);Check(Object.ReferenceEquals(page,((TabItem)tabs.Items[0]).Content)&&Flat((DiagnosticUiSnapshot)Get(desktop,"historyDiagnosticView")).Contains("Verified messages imported: 13"),"in-place live refresh");
        foreach(TabItem tab in tabs.Items){tabs.SelectedItem=tab;window.UpdateLayout();((TextBlock)Get(desktop,"diagnosticBanner")).Text="SAMPLE FIXTURE — NOT PHYSICAL ACCEPTANCE";Capture(window,System.IO.Path.Combine(directory,"History-"+tab.Header+".png"));Check(tab.Content!=null,"history populated tab");}
        input.Scope="other-profile";await Task.Delay(1400);Check(!((HistoryDiagnosticInput)Get(desktop,"historyDiagnosticInput")).Current,"selected scope cannot adopt other profile");window.Close();Check(((List<Action>)Get(desktop,"historyDiagnosticRefreshes")).Count==0,"callbacks released");Set(desktop,"historyDiagnosticTestInput",null);
        Call(desktop,"OpenContextDiagnostics",DiagnosticSection.HistorySync,"");Check(!Flat((DiagnosticUiSnapshot)Get(desktop,"historyDiagnosticView")).Contains("22"),"real idle provider does not borrow fixture completion");Check(!((string)Call(desktop,"CurrentDiagnosticExport")).Contains("SAMPLE"),"normal export not sample");((Window)Get(desktop,"groupDiagnosticWindow")).Close();
        Console.WriteLine("PASS: History diagnostics cached read-only ownership, source/import accounting, current/completed separation, partial/unavailable, safe evidence/export, bounded events, live refresh and cleanup.");
    }
}
